function wrapLines(s,x,y,size){const words=String(s).split(' '),max=Math.floor(900/size),lines=[''];for(const w of words){if((lines.at(-1)+' '+w).trim().length>max&&lines.at(-1))lines.push(w);else lines[lines.length-1]=(lines.at(-1)+' '+w).trim();}return lines.map((v,i)=>`<tspan x="${x}" y="${y+i*(size+4)}">${esc(v)}</tspan>`).join('');}
import{experimentOptions,experimentResult,outputLabel}from './frc1-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const text=(x,y,s,size=16)=>`<text x="${x}" y="${y}" font-size="${size}" fill="#f6f3ed" text-anchor="middle">${wrapLines(s,x,y,size)}</text>`;const line=(x,y,a,b,c='#a8c9c8',w=2)=>`<path d="M${x} ${y} L${a} ${b}" stroke="${c}" stroke-width="${w}" fill="none"/>`;const arrow=(x,y,a,b,c='#ef927e')=>line(x,y,a,b,c,4)+`<path d="M${a-10*Math.cos(Math.atan2(b-y,a-x)-.5)} ${b-10*Math.sin(Math.atan2(b-y,a-x)-.5)} L${a} ${b} L${a-10*Math.cos(Math.atan2(b-y,a-x)+.5)} ${b-10*Math.sin(Math.atan2(b-y,a-x)+.5)}" fill="none" stroke="${c}" stroke-width="3"/>`;const block=(x,y,label,w=80)=>`<rect x="${x-w/2}" y="${y-30}" width="${w}" height="60" rx="12" fill="url(#frc1-body)" stroke="#e4edea" stroke-opacity=".4"/>${text(x,y+6,label,14)}`;const wheel=(x,y)=>`<circle cx="${x}" cy="${y}" r="10" fill="#12283a" stroke="#bcd0cf"/>`;const cart=(x,y,label)=>block(x,y,label)+wheel(x-25,y+35)+wheel(x+25,y+35);
const fmt=v=>Number(v.toFixed(3));
export function forceFigure({kind='resultant',movie=false,progress=.5,a,b,revealed=false}={}){const k=kind.split('-')[0],o=experimentOptions[k]||experimentOptions.resultant,A=String(a??o.a[0][0]),B=String(b??o.b[0][0]),x=Number(A),y=Number(B),p=movie?Math.min(1,Math.max(0,progress)):.5;let s='',header='',footer='';
if(['vectors','resultant','thirdlaw','weight','terminal','firstlaw','secondlaw','accelpractical'].includes(k)){
 let cx=280;if(movie&&['firstlaw','secondlaw'].includes(k))cx=130+(k==='firstlaw'?260*p:260*p*p);
 s+=line(55,315,505,315)+cart(cx,270,k==='weight'?'mass':k==='thirdlaw'?'A':'object');
 if(k==='weight'){s+=arrow(cx,275,cx,275+Math.min(130,x*y*2))+text(cx+80,345,'W = mg');header='Weight acts toward the attracting body';}
 else if(k==='terminal'){let wt=movie?20:x,dr=movie?20*p:y;s+=arrow(cx-20,270,cx-20,270+wt*4)+arrow(cx+20,270,cx+20,270-dr*4,'#a8c9c8');header='Downward weight versus upward drag';s+=text(100,220,'Weight '+wt+' N',13)+text(450,220,'Drag '+fmt(dr)+' N',13);}
 else if(k==='thirdlaw'){s+=cart(440,270,'B')+arrow(310,245,310+x*y*3,245)+arrow(410,215,410-x*y*3,215,'#a8c9c8');header='Partner forces act on different objects';footer='A-on-B and B-on-A: equal magnitudes, opposite directions';}
 else if(k==='vectors'){s+=arrow(cx,230,cx+x*y*6,230)+text(280,160,'Right is positive');header='A scaled force arrow is not a motion track';}
 else if(k==='resultant'){s+=arrow(cx+40,250,cx+40+x*5,250)+arrow(cx-40,250,cx-40-y*5,250,'#a8c9c8')+text(430,190,'Drive '+x+' N',14)+text(110,190,'Resistance '+y+' N',14);header='Add forces on the same chosen object';}
 else if(k==='firstlaw'){header=movie?'Ideal coast: zero resultant, constant velocity':'Drive and resistance determine velocity change';s+=text(280,190,A==='ideal'?'No resistance':'Resistance present')+text(280,370,B==='remove'?'Drive removed':'Drive balances resistance');}
 else{s+=arrow(cx,220,cx+x*8,220)+text(280,170,'F = '+x+' N; m = '+y+' kg');header='Acceleration follows resultant force / mass';}
}
else if(k==='components'){let scale=22,xx=x*scale,yy=y*scale;s+=line(130,315,130+xx,315)+line(130+xx,315,130+xx,315-yy)+arrow(130,315,130+xx,315-yy)+arrow(130,315,130+xx,315,'#a8c9c8')+arrow(130,315,130,315-yy,'#a8c9c8')+text(280,355,'Horizontal '+x+' N · vertical '+y+' N');header='One diagonal, two equivalent perpendicular components';footer='Read direction as well as magnitude · constrained scale drawing';}
else if(['elasticity','springs'].includes(k)){let force=k==='elasticity'?y:x*y,e=k==='elasticity'?y/x:y,extension=(movie?p:e/.04)*60,end=235+extension;let pts=Array.from({length:25},(_,i)=>`${280+(i%2?18:-18)},${110+i*(end-110)/24}`).join(' ');s+=line(200,100,360,100)+`<polyline points="280,100 ${pts} 280,${end}" fill="none" stroke="#d3e7dd" stroke-width="4"/>`+block(280,end+35,'load')+arrow(280,end+65,280,end+105)+text(420,200,'Original length',13)+line(360,110,360,235)+text(430,285,'Extension e',14)+line(360,235,360,end);header='Linear elastic region · F = ke';footer=k==='springs'?'Ideal data: evaluate real resolution, parallax and repeatability':'Extension is a change in length, not the whole length';}
else if(k==='moments'){let tilt=movie?Math.sin(p*Math.PI)*.12:0;s+=`<g transform="rotate(${tilt*180/Math.PI} 280 250)">${line(85,250,475,250,'#c5dbd5',12)}${arrow(280-x*0+y*130,250,280+y*130,250+x*10)}${arrow(150,250,150,290,'#a8c9c8')}</g><path d="M260 295 L280 255 L300 295Z" fill="#c5dbd5"/>`+text(280,350,'Opposing moment:4 N at1 m =4 N m')+text(280,390,`Applied ${x} N at perpendicular ${y} m`);header='Moment = force × perpendicular distance';footer='The pivot is fixed · compare clockwise and anticlockwise totals';}
else if(['pressure','depth','atmosphere'].includes(k)){s+=`<path d="M120 110 V330 H440 V110" fill="#89b6be" fill-opacity=".15" stroke="#b9d8d2" stroke-width="3"/>`;if(k==='pressure'){s+=block(280,230,'surface',130)+arrow(280,150,280,200)+arrow(180,230,210,230)+arrow(380,230,350,230)+text(280,365,`Normal force ${x} N · area ${y} m²`);header='Pressure acts at right angles to a surface';}
 else if(k==='depth'){let top=130,cy=180+x*35;s+=line(120,top,440,top)+block(280,cy,'block',65)+arrow(280,cy-75,280,cy-32,'#a8c9c8')+arrow(280,cy+85,280,cy+33)+text(280,385,`h=${x} m · ρ=${y} kg/m³ · g=10 N/kg`);header='Greater depth → greater liquid pressure';footer='Greater bottom pressure produces upthrust · arrows schematic';}
 else{for(let i=0;i<30;i++){let yy=140+(i*43)%170,xx=145+(i*71)%270;s+=`<circle cx="${xx+Math.sin(p*6+i)*5}" cy="${yy}" r="4" fill="#c7dfd7" opacity="${.25+(yy-130)/300}"/>`;}header='Atmospheric density and pressure decrease with altitude';s+=text(280,365,A==='low'?'Lower comparison site':'Higher comparison site')+text(280,400,'Collisions transfer momentum to surfaces',14);}}
else if(['distancegraph','velocitygraph'].includes(k)){let height=180,run=300;s+=line(80,330,480,330)+line(80,330,80,100)+line(80,330,80+run,330-height,'#ef927e',4)+line(80,330-height,80+run,330-height,'#78939a')+line(80+run,330,80+run,330-height,'#78939a')+`<circle cx="${80+run*p}" cy="${330-height*p}" r="7" fill="#eac884"/>`+text(280,370,'Δt = '+y+' s')+text(280,90,(k==='distancegraph'?'Distance':'Velocity')+' change = '+x+(k==='distancegraph'?' m':' m/s'));
header=k==='distancegraph'?'Distance–time: gradient gives speed':'Velocity–time: gradient gives acceleration';footer='Read both axis quantities · original constructed comparison';}
else if(['collisions','momentum','impact'].includes(k)){let pos=k==='collisions'?(p<.5?110+p*260:240+(p-.5)*200):k==='momentum'?280+(y<0?-1:1)*(p-.5)*250:100+260*(2*p-p*p);s+=line(60,320,500,320)+cart(pos,270,k==='impact'?'2 kg':x+' kg');if(k==='collisions')s+=cart(p<.5?325:325+(p-.5)*200,270,'2 kg');if(k==='momentum')s+=arrow(pos,215,pos+Math.sign(y)*90,215);header=k==='collisions'?'One ideal sticking collision':k==='impact'?'Same stopping change, different duration':'Momentum includes direction';footer=k==='impact'?'Average force is not peak force or injury prediction':'Define the system · ignore external force only when justified';}
else if(['work','motion','acceleration','stopping','braking'].includes(k)){let z=p;if(k==='acceleration')z=p*p;if(k==='braking')z=2*p-p*p;let pos=90+360*z;s+=line(55,320,505,320)+cart(pos,270,k==='braking'?'1000 kg':'object');if(k==='work')s+=arrow(pos,220,pos+60,220);s+=text(280,370,k==='work'?`Force ${x} N · displacement ${y} m`:k==='stopping'?`Thinking interval: ${y} s at ${x} m/s`:k==='acceleration'?`From rest: a=${x} m/s²; t=${y} s`:k==='braking'?`Initial ${x} m/s · opposing ${y} N`:`Constant ${x} m/s for ${y} s`);header=k==='stopping'?'Thinking distance comes before brake application':k==='braking'?'Kinetic energy → internal energy':k==='acceleration'?'Position changes faster as velocity increases':k==='work'?'Work is force through along-force displacement':'Equal times, equal distances at constant speed';footer='Replay resets a worked example · distances scaled for clarity';}
if(revealed)s+=text(280,455,outputLabel(k,experimentResult(k,A,B).value),15);
return `<svg class="shell-diagram frc1-diagram" viewBox="0 0 560 480" role="img" aria-label="${esc(k+' labelled force/motion model'+(revealed?' with revealed result':''))}"><defs><linearGradient id="frc1-body" x2=".8" y2="1"><stop stop-color="#8aaeb1"/><stop offset="1" stop-color="#31516b"/></linearGradient></defs>${text(280,50,header,15)}${s}${text(280,420,footer,12)}</svg>`;}
